<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Submission Review | AppTasker</title><style>body{margin:0;background:#f5f7fb;font-family:Inter,system-ui;color:#182230}.w{max-width:1100px;margin:auto;padding:24px 16px}.back{color:#526df5;text-decoration:none;font-weight:800}.msg{background:#ecfdf3;color:#087a48;padding:13px;border-radius:12px}.card{background:#fff;border:1px solid #e7eaf0;border-radius:18px;padding:19px;margin:14px 0}.head{display:flex;justify-content:space-between;gap:15px}.muted{color:#667085;font-size:13px}.actions{display:grid;grid-template-columns:1fr auto auto;gap:8px;margin-top:15px}.note{padding:11px;border:1px solid #d7dce5;border-radius:10px}.btn{border:0;padding:11px 15px;border-radius:10px;color:#fff;font-weight:800}.ok{background:#12b76a}.no{background:#f04438}@media(max-width:650px){.actions{grid-template-columns:1fr}.head{display:block}}</style></head><body><main class="w"><a class="back" href="{{ route('admin.dashboard') }}">← Admin Dashboard</a><h1>Submission Review</h1>@if(session('success'))<p class="msg">{{ session('success') }}</p>@endif @forelse($submissions as $s)<section class="card"><div class="head"><div><strong>{{ $s->workerTask->task->title }}</strong><div class="muted">Worker: {{ $s->workerTask->user->name }} · {{ $s->workerTask->user->email }}</div><div class="muted">File: {{ $s->original_name }} · {{ number_format(($s->file_size ?? 0)/1024,1) }} KB</div></div><strong>{{ ucfirst($s->status) }}</strong></div>@if($s->status==='pending')<form class="actions" method="POST" action="{{ route('admin.submissions.review',$s) }}">@csrf @method('PATCH')<input class="note" name="verification_notes" placeholder="Verification notes (optional)"><button class="btn ok" name="status" value="approved">Approve</button><button class="btn no" name="status" value="rejected">Reject</button></form>@else<p class="muted">Review note: {{ $s->verification_notes ?: 'No note' }}</p>@endif</section>@empty<p>No submissions yet.</p>@endforelse{{ $submissions->links() }}</main></body></html>